#include <stdio.h>

int main(void) {
    int n, a[10][10];
    int missing_row = 0, missing_col = 0;

    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            if (a[i][j] == 0) {
                missing_row = i;
                missing_col = j;
            }
        }
    }

    int magic_sum = 0;
    for (int i = 0; i < n; i++) {
        if (i == missing_row) continue;
        for (int j = 0; j < n; j++) {
            magic_sum += a[i][j];
        }
        break;
    }

    int known_sum = 0;
    for (int j = 0; j < n; j++) {
        known_sum += a[missing_row][j];
    }

    printf("%d\n%d\n%d\n", magic_sum - known_sum,
           missing_row + 1, missing_col + 1);

    return 0;
}
